"""
Utility functions to write OPM/pofff files and variables.
"""

import os
import subprocess
from dataclasses import asdict
from mako.template import Template
import numpy as np

# Standard header added to all generated include files
HEADER = (
    "-- Copyright (C) 2025-2026 NORCE Research AS\n"
    "-- This deck was generated by pofff https://github.com/cssr-tools/pofff\n"
)


# =============================================================================
# Compact formatting
# =============================================================================


def compact_format(values):
    """
    Encode values using Eclipse-style n*value compaction.
    Uses NumPy for efficient run-length encoding.
    """
    if len(values) == 0:
        return []

    v = np.asarray(values, dtype=np.float64)

    # Detect value changes
    change = np.concatenate(([True], v[1:] != v[:-1]))
    idx = np.flatnonzero(change)
    counts = np.diff(np.append(idx, v.size))
    uniq = v[idx]

    out = []

    for val, n in zip(uniq, counts):
        if n > 1:
            if val == 0:
                out.append(f"{n}*0 ")
            elif val.is_integer():
                out.append(f"{n}*{int(val)} ")
            else:
                out.append(f"{n}*{val} ")
        else:
            if val == 0:
                out.append("0 ")
            elif val.is_integer():
                out.append(f"{int(val)} ")
            else:
                out.append(f"{val} ")

    return out


# =============================================================================
# Corner-point grid writer (COORD + ZCORN)
# =============================================================================


def create_corner_point_grid(cfg, xcoord, zcoord):
    """
    Write COORD and ZCORN sections for a corner-point grid.
    Output is bit-identical to the original implementation.
    """

    nx, nz = cfg.nxz
    nk = nz + 1

    grid = []
    grid.append("COORD\n")
    tmp = []

    # Write pillar coordinates
    for y in [0, cfg.dims[1]]:
        for i in range(nx + 1):
            base = i * nk
            tmp.append(f"{xcoord[base]:E} {y} 0 " f"{xcoord[base + nz]:E} {y:E} 0 ")

    grid.extend(compact_format("".join(tmp).split()))
    grid.append("/\n")

    # Write ZCORN values
    grid.append("ZCORN\n")
    tmp = []

    # Top layer
    for i in range(nx):
        tmp.append(f"{zcoord[i*nk]:E} {zcoord[(i+1)*nk]:E} ")
    tmp.extend(tmp[-nx:])

    # Interior layers
    for k in range(nz - 1):
        for i in range(nx):
            base = i * nk + k + 1
            tmp.append(f"{zcoord[base]:E} {zcoord[base + nk]:E} ")
        tmp.extend(tmp[-nx:])
        tmp.extend(tmp[-2 * nx :])

    # Bottom layer
    for i in range(nx):
        tmp.append(f"{zcoord[(i+1)*nk - 1]:E} {zcoord[(i+2)*nk - 1]:E} ")
    tmp.extend(tmp[-nx:])

    grid.extend(compact_format("".join(tmp).split()))
    grid.append("/")

    # Write GRID include file
    with open(f"{cfg.deck}/GRID.INC", "w", encoding="utf8") as f:
        f.write(HEADER)
        f.write("".join(grid))
        f.write("\n")


# =============================================================================
# Keyword writers
# =============================================================================


def write_keywords(cfg):
    """
    Write OPM keyword include files (FIPNUM, FLUXNUM, DX, DZ, etc.).
    """
    keywords = ["fluxnum", "fipnum"]

    if cfg.grid == "tensor":
        keywords += ["dx", "dz"]

    if cfg.thickness in ("initial", "final"):
        keywords += ["multpv", "multx", "multx-", "multz", "multz-"]

    for name in keywords:
        values = getattr(cfg, "multpv" if name.startswith("mult") else name)
        body = compact_format(values)

        with open(f"{cfg.deck}/{name.upper()}.INC", "w", encoding="utf8") as f:
            f.write(HEADER)
            f.write(f"{name.upper()}\n")
            f.writelines(body)
            f.write("/\n")


# =============================================================================
# Main file generation
# =============================================================================


def write_files(cfg):
    """
    Generate all OPM, ERT, and Everest files using mako templates.
    """
    write_keywords(cfg)

    # --------------------------------------------------
    # Main DATA deck
    # --------------------------------------------------
    tmpl = Template(filename=f"{cfg.path}/templates/deck.mako")
    with open(f"{cfg.deck}/{cfg.data}.DATA", "w", encoding="utf8") as f:
        f.write(tmpl.render(dic=asdict(cfg)))

    job_names = ["bcprop", "equalreg", "satufunc"]

    # --------------------------------------------------
    # ERT / Everest configuration
    # --------------------------------------------------
    if cfg.everert:
        job_names += ["flow", "copyd"]

        if cfg.popsize:
            cfg_name = "everest"
            job_names.append("scale")

            with open(f"{cfg.jobs}/METRIC", "w", encoding="utf8") as f:
                f.write("EXECUTABLE metric.py")

            with open(f"{cfg.jobs}/DATA", "w", encoding="utf8") as f:
                f.write("EXECUTABLE data.py")

        else:
            cfg_name = "ert"

            with open(f"{cfg.jobs}/METRIC", "w", encoding="utf8") as f:
                f.write("EXECUTABLE metric.py\n")
                f.write(
                    f"ARGLIST -t {cfg.times} -e {cfg.experiment} "
                    f"-s {cfg.msat} -c {cfg.mcon} -p {cfg.path}"
                )

            with open(f"{cfg.jobs}/DATA", "w", encoding="utf8") as f:
                f.write("EXECUTABLE data.py\n")
                f.write(f"ARGLIST -t {cfg.times} -m {cfg.deck}/cellmap.npy")

        if cfg.monotonic:
            job_names.append("monotonic")

        tmpl = Template(filename=f"{cfg.path}/templates/{cfg_name}.mako")
        with open(
            f"{cfg.fol}/{cfg_name}.{'yml' if cfg.popsize else 'txt'}",
            "w",
            encoding="utf8",
        ) as f:
            f.write(tmpl.render(dic=asdict(cfg)))

    # --------------------------------------------------
    # Job scripts
    # --------------------------------------------------
    for name in job_names:
        tmpl = Template(filename=f"{cfg.path}/templates/{name}.mako")
        script_path = f"{cfg.jobs}/{name}.py"

        if os.path.exists(script_path):
            os.remove(script_path)

        with open(script_path, "w", encoding="utf8") as f:
            f.write(tmpl.render(dic=asdict(cfg)))

        os.chmod(script_path, 0o755)

        # Inline execution for single/files mode
        if cfg.mode in ["single", "files"] and not cfg.everert:
            subprocess.run(["python3", script_path], check=True)
            os.remove(script_path)

    # --------------------------------------------------
    # Extra ERT input files
    # --------------------------------------------------
    if cfg.ertargs and cfg.everert:
        for name in ("prior", "para", "obs"):
            tmpl = Template(filename=f"{cfg.path}/templates/{name}.mako")
            suffix = "tmpl" if name == "prior" else "txt"
            with open(f"{cfg.deck}/{name}.{suffix}", "w", encoding="utf8") as f:
                f.write(tmpl.render(dic=asdict(cfg)))
